const LESSONS=[{"title":"School Words","words":[{"w":"arrive","m":"to reach a place","e":"We arrive at school before the bell."},{"w":"borrow","m":"to use something and give it back later","e":"I borrow a book from the library."},{"w":"careful","m":"taking time to avoid mistakes or danger","e":"Be careful when carrying the glass."},{"w":"choose","m":"to pick one thing from several","e":"You may choose a blue or red pencil."},{"w":"collect","m":"to bring things together","e":"We collect our books after class."},{"w":"explain","m":"to make an idea clear","e":"The teacher will explain the new game."},{"w":"finish","m":"to complete something","e":"I finish my work before lunch."},{"w":"notice","m":"to see or become aware of something","e":"Did you notice the rainbow?"},{"w":"remember","m":"to keep something in your mind","e":"Remember to bring your hat."},{"w":"share","m":"to let others use or have part of something","e":"We share the crayons."}]},{"title":"Feelings","words":[{"w":"amazed","m":"very surprised","e":"I was amazed by the huge whale."},{"w":"anxious","m":"worried or nervous","e":"Sam felt anxious before the race."},{"w":"calm","m":"peaceful and not worried","e":"Mia stayed calm during the storm."},{"w":"cheerful","m":"happy and positive","e":"His cheerful smile made us laugh."},{"w":"cross","m":"angry or annoyed","e":"Dad was cross about the muddy floor."},{"w":"curious","m":"wanting to know more","e":"The curious child asked many questions."},{"w":"disappointed","m":"sad because something did not happen as hoped","e":"I felt disappointed when the game was cancelled."},{"w":"excited","m":"very happy and eager","e":"We were excited about the school trip."},{"w":"proud","m":"pleased about something you did well","e":"She felt proud of her painting."},{"w":"worried","m":"thinking something may go wrong","e":"I was worried about the lost puppy."}]},{"title":"Movement","words":[{"w":"crawl","m":"to move on hands and knees or close to the ground","e":"The baby can crawl across the mat."},{"w":"dash","m":"to run quickly","e":"We dash to the shelter when rain starts."},{"w":"drag","m":"to pull something along the ground","e":"Do not drag the bag on the floor."},{"w":"glide","m":"to move smoothly and quietly","e":"The swan can glide across the lake."},{"w":"hurry","m":"to move or act quickly","e":"We hurry so we do not miss the bus."},{"w":"leap","m":"to jump a long way or high","e":"The frog can leap over the rock."},{"w":"march","m":"to walk with regular strong steps","e":"The band will march down the street."},{"w":"race","m":"to move quickly against others","e":"The children race to the tree."},{"w":"stroll","m":"to walk slowly and calmly","e":"We stroll through the park."},{"w":"tumble","m":"to fall or roll suddenly","e":"The blocks tumble from the tower."}]},{"title":"Describing Words","words":[{"w":"ancient","m":"very old","e":"We saw an ancient tree in the park."},{"w":"bright","m":"giving lots of light or strong colour","e":"The bright sun shone through the window."},{"w":"enormous","m":"very large","e":"An enormous truck passed us."},{"w":"gentle","m":"kind, soft or not rough","e":"Use a gentle voice with the baby."},{"w":"narrow","m":"not wide","e":"We walked along a narrow path."},{"w":"noisy","m":"making a lot of sound","e":"The playground was noisy at lunch."},{"w":"rough","m":"not smooth","e":"The tree bark felt rough."},{"w":"shiny","m":"smooth and reflecting light","e":"I found a shiny coin."},{"w":"tiny","m":"very small","e":"A tiny ant climbed the leaf."},{"w":"wide","m":"having a large distance from side to side","e":"The river is wide near the bridge."}]},{"title":"Nature","words":[{"w":"breeze","m":"a light wind","e":"A cool breeze moved the leaves."},{"w":"branch","m":"a part of a tree that grows from the trunk","e":"A bird sat on the branch."},{"w":"coast","m":"land beside the sea","e":"We drove along the coast."},{"w":"creek","m":"a small stream","e":"We crossed the creek on stepping stones."},{"w":"forest","m":"a large area covered with trees","e":"Many animals live in the forest."},{"w":"island","m":"land completely surrounded by water","e":"The boat sailed around the island."},{"w":"pebble","m":"a small smooth stone","e":"I picked up a round pebble."},{"w":"shadow","m":"a dark shape made when light is blocked","e":"My shadow stretched across the path."},{"w":"storm","m":"bad weather with strong wind, rain or thunder","e":"The storm passed during the night."},{"w":"valley","m":"low land between hills or mountains","e":"A river ran through the valley."}]},{"title":"Time and Order","words":[{"w":"after","m":"later than something else","e":"We played outside after lunch."},{"w":"before","m":"earlier than something else","e":"Wash your hands before dinner."},{"w":"early","m":"before the expected time","e":"We arrived early for the show."},{"w":"finally","m":"at the end after waiting or effort","e":"Finally, the bus arrived."},{"w":"first","m":"before all others in order","e":"First, open your book."},{"w":"later","m":"after some time","e":"We will finish the game later."},{"w":"next","m":"coming immediately after","e":"Next, add the water."},{"w":"soon","m":"after a short time","e":"The rain will stop soon."},{"w":"suddenly","m":"quickly and unexpectedly","e":"Suddenly, the lights went out."},{"w":"yesterday","m":"the day before today","e":"Yesterday, we visited Grandma."}]},{"title":"Community Places","words":[{"w":"bakery","m":"a place where bread and cakes are made or sold","e":"We bought bread at the bakery."},{"w":"clinic","m":"a place where people receive medical care","e":"The nurse works at the clinic."},{"w":"library","m":"a place where books can be borrowed","e":"I returned my book to the library."},{"w":"market","m":"a place where people buy and sell goods","e":"We bought fruit at the market."},{"w":"museum","m":"a place that displays interesting or important objects","e":"We saw dinosaur bones at the museum."},{"w":"neighbour","m":"a person who lives near you","e":"Our neighbour watered the garden."},{"w":"station","m":"a place where trains or buses stop","e":"We waited at the train station."},{"w":"traffic","m":"vehicles moving along roads","e":"There was heavy traffic this morning."},{"w":"village","m":"a small community in the countryside","e":"The village has a small shop."},{"w":"volunteer","m":"a person who chooses to help without being paid","e":"A volunteer helped clean the park."}]},{"title":"Useful Opposites","words":[{"w":"empty","m":"having nothing inside","e":"The bottle is empty."},{"w":"full","m":"holding as much as possible","e":"The basket is full of apples."},{"w":"include","m":"to have something as part of a group","e":"The list will include every student."},{"w":"exclude","m":"to leave something out","e":"Do not exclude anyone from the game."},{"w":"increase","m":"to become or make greater","e":"The number of plants will increase."},{"w":"decrease","m":"to become or make smaller","e":"The water level began to decrease."},{"w":"similar","m":"almost the same","e":"The two pictures look similar."},{"w":"different","m":"not the same","e":"The twins chose different hats."},{"w":"possible","m":"able to happen or be done","e":"It is possible to finish today."},{"w":"impossible","m":"not able to happen or be done","e":"It is impossible to fit the huge box in the bag."}]},{"title":"Compound Words","words":[{"w":"playground","m":"an outdoor place for children to play","e":"We met near the playground."},{"w":"toothbrush","m":"a small brush used to clean teeth","e":"Put toothpaste on your toothbrush."},{"w":"sunflower","m":"a tall plant with a large yellow flower","e":"A sunflower grew beside the fence."},{"w":"raincoat","m":"a waterproof coat worn in rain","e":"I wore my raincoat to school."},{"w":"bedroom","m":"a room used for sleeping","e":"My books are in my bedroom."},{"w":"football","m":"a ball used in football games","e":"He kicked the football."},{"w":"lunchtime","m":"the time when lunch is eaten","e":"We talk quietly at lunchtime."},{"w":"mailbox","m":"a box where letters are placed or delivered","e":"A letter was in the mailbox."},{"w":"seashell","m":"the hard outer covering of a sea animal","e":"We found a seashell on the beach."},{"w":"weekend","m":"Saturday and Sunday","e":"We visit our cousins on the weekend."}]},{"title":"Homophones","words":[{"w":"pair","m":"two things that belong together","e":"I bought a pair of socks."},{"w":"pear","m":"a sweet fruit with a rounded bottom","e":"She sliced a ripe pear."},{"w":"sea","m":"a large area of salt water","e":"The sea was calm today."},{"w":"see","m":"to use your eyes to notice something","e":"I can see a bird in the tree."},{"w":"right","m":"correct or the direction opposite left","e":"Your answer is right."},{"w":"write","m":"to make words with a pen, pencil or keyboard","e":"Please write your name."},{"w":"one","m":"the number 1","e":"I have one blue pencil."},{"w":"won","m":"past tense of win","e":"Our team won the game."},{"w":"blue","m":"a colour like a clear sky","e":"The kite is blue."},{"w":"blew","m":"past tense of blow","e":"The wind blew all night."}]},{"title":"Word Building","words":[{"w":"unhappy","m":"not happy","e":"The child felt unhappy when the toy broke."},{"w":"reread","m":"to read again","e":"Reread the question carefully."},{"w":"dislike","m":"to not like something","e":"I dislike very loud music."},{"w":"hopeful","m":"feeling that something good may happen","e":"We felt hopeful about finding the dog."},{"w":"careless","m":"not giving enough care or attention","e":"A careless mistake changed the answer."},{"w":"slowly","m":"in a slow way","e":"The snail moved slowly."},{"w":"kindness","m":"the quality of being kind","e":"Her kindness made the new student feel welcome."},{"w":"playful","m":"full of fun and wanting to play","e":"The playful puppy chased the ball."},{"w":"teacher","m":"a person who teaches","e":"Our teacher read us a story."},{"w":"payment","m":"money given for something","e":"Dad made the payment at the counter."}]},{"title":"Strong Everyday Words","words":[{"w":"discover","m":"to find or learn something new","e":"We discover new facts when we read."},{"w":"protect","m":"to keep safe from harm","e":"A helmet can protect your head."},{"w":"rescue","m":"to save someone or something from danger","e":"The firefighters rescue the kitten."},{"w":"gather","m":"to bring or come together","e":"We gather around the table."},{"w":"compare","m":"to look at how things are alike or different","e":"Compare the two pictures."},{"w":"decide","m":"to make a choice","e":"We decide which game to play."},{"w":"improve","m":"to make or become better","e":"Practice can improve your spelling."},{"w":"prepare","m":"to get ready","e":"We prepare our bags the night before school."},{"w":"problem","m":"something difficult that needs a solution","e":"We worked together to solve the problem."},{"w":"solution","m":"an answer to a problem","e":"The class found a simple solution."}]}];
const $ = id => document.getElementById(id);
const MODE_NAMES = {
  meaning: 'Meaning',
  context: 'In a Sentence',
  spelling: 'Spelling',
  mixed: 'Mixed Review'
};
const PRACTICE_SIZE = 6;
let lesson = 0;
let mode = 'meaning';
let questions = [];

function progressKey() {
  return 'skillup-vocab-y2-progress';
}

function getProgress() {
  try {
    return JSON.parse(localStorage.getItem(progressKey())) || [];
  } catch (error) {
    return [];
  }
}

function markDone() {
  const progress = getProgress();
  if (!progress.includes(lesson)) {
    progress.push(lesson);
    localStorage.setItem(progressKey(), JSON.stringify(progress));
  }
  renderProgress();
  renderLessons();
}

function shuffle(values) {
  return [...values].sort(() => Math.random() - .5);
}

function variants(word) {
  const spellings = new Set([word]);
  if (word.length > 3) {
    spellings.add(word.slice(0, -1));
    spellings.add(word.slice(0, 1) + word[1] + word.slice(1));
    const letters = word.split('');
    const index = Math.min(2, letters.length - 2);
    [letters[index], letters[index + 1]] = [letters[index + 1], letters[index]];
    spellings.add(letters.join(''));
  }
  while (spellings.size < 4) spellings.add(word + 'e'.repeat(spellings.size));
  return shuffle([...spellings]).slice(0, 4);
}

function makeQuestions() {
  const currentLesson = LESSONS[lesson];
  const allWords = LESSONS.flatMap(item => item.words);
  const pool = currentLesson.words.map(word => {
    const type = mode === 'mixed'
      ? ['meaning', 'context', 'spelling'][Math.floor(Math.random() * 3)]
      : mode;

    if (type === 'meaning') {
      const distractors = shuffle(allWords.filter(item => item.w !== word.w).map(item => item.m)).slice(0, 3);
      return {
        q: `What does “${word.w}” mean?`,
        a: word.m,
        c: shuffle([word.m, ...distractors]),
        tip: word.e
      };
    }

    if (type === 'context') {
      const escapedWord = word.w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const sentence = word.e.replace(new RegExp(`\\b${escapedWord}\\b`, 'i'), '_____');
      const distractors = shuffle(allWords.filter(item => item.w !== word.w).map(item => item.w)).slice(0, 3);
      return {
        q: `Choose the word that completes the sentence: ${sentence}`,
        a: word.w,
        c: shuffle([word.w, ...distractors]),
        tip: word.m
      };
    }

    return {
      q: `Which spelling is correct for the word meaning “${word.m}”?`,
      a: word.w,
      c: variants(word.w),
      tip: word.e
    };
  });

  questions = shuffle(pool).slice(0, PRACTICE_SIZE);
}

function renderProgress() {
  $('progress').textContent = `${getProgress().length} / ${LESSONS.length} complete`;
}

function renderLessons() {
  const progress = getProgress();
  $('lessonButtons').innerHTML = LESSONS.map((item, index) =>
    `<button data-i="${index}" class="${index === lesson ? 'active' : ''}">${index + 1}. ${item.title}${progress.includes(index) ? ' ✓' : ''}</button>`
  ).join('');
  document.querySelectorAll('#lessonButtons button').forEach(button => {
    button.onclick = () => {
      lesson = Number(button.dataset.i);
      makeQuestions();
      renderAll();
    };
  });
}

function renderWords() {
  const currentLesson = LESSONS[lesson];
  $('lessonTag').textContent = `LESSON ${lesson + 1}`;
  $('lessonTitle').textContent = currentLesson.title;
  $('wordCards').innerHTML = currentLesson.words.map(word =>
    `<article class="word-card"><b>${word.w}</b><p>${word.m}</p><small>${word.e}</small></article>`
  ).join('');
}

function renderQuestions() {
  const list = $('questionList');
  const summary = $('quizSummary');
  let answeredCount = 0;
  let correctCount = 0;

  $('qCount').textContent = `${PRACTICE_SIZE} QUESTIONS`;
  $('modeName').textContent = MODE_NAMES[mode];
  summary.textContent = '';
  list.innerHTML = '';

  questions.forEach((question, questionIndex) => {
    const card = document.createElement('article');
    card.className = 'practice-question';

    const number = document.createElement('span');
    number.className = 'question-number';
    number.textContent = `QUESTION ${questionIndex + 1} OF ${PRACTICE_SIZE}`;

    const heading = document.createElement('h3');
    heading.textContent = question.q;

    const answers = document.createElement('div');
    answers.className = 'answers';

    const feedback = document.createElement('div');
    feedback.className = 'feedback';
    feedback.setAttribute('role', 'status');
    feedback.setAttribute('aria-live', 'polite');

    question.c.forEach(choice => {
      const button = document.createElement('button');
      button.type = 'button';
      button.textContent = choice;
      button.onclick = () => {
        if (card.dataset.answered === 'true') return;
        card.dataset.answered = 'true';
        answeredCount++;
        const isCorrect = String(choice) === String(question.a);
        if (isCorrect) {
          correctCount++;
          button.classList.add('correct');
          feedback.textContent = `✓ Correct! ${question.tip}`;
        } else {
          button.classList.add('wrong');
          [...answers.children].find(item => item.textContent === String(question.a))?.classList.add('correct');
          feedback.textContent = `Not quite. Correct answer: ${question.a}. ${question.tip}`;
        }
        [...answers.children].forEach(item => { item.disabled = true; });

        if (answeredCount === questions.length) {
          markDone();
          summary.textContent = `Set complete: ${correctCount} / ${questions.length} correct. Select “New set of 6” for more practice.`;
        } else {
          summary.textContent = `${answeredCount} of ${questions.length} questions answered.`;
        }
      };
      answers.appendChild(button);
    });

    card.appendChild(number);
    card.appendChild(heading);
    card.appendChild(answers);
    card.appendChild(feedback);
    list.appendChild(card);
  });
}

function renderAll() {
  renderLessons();
  renderWords();
  renderProgress();
  document.querySelectorAll('.mode-tabs button').forEach(button => {
    button.classList.toggle('active', button.dataset.mode === mode);
  });
  renderQuestions();
}

document.querySelectorAll('.mode-tabs button').forEach(button => {
  button.onclick = () => {
    mode = button.dataset.mode;
    makeQuestions();
    renderAll();
  };
});

$('newSet').onclick = () => {
  makeQuestions();
  renderQuestions();
  $('questionList').scrollIntoView({behavior: 'smooth', block: 'start'});
};

makeQuestions();
renderAll();
